import { Component, inject, OnInit } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { FormsModule } from '@angular/forms';
import { MessagesService } from './messages.service';

interface Manufacturer { id?: number; name: string; }
interface Car { id?: number; model: string; manufacturer?: Manufacturer; }
interface Rating { id?: number; rating: number; car: Car; }
interface MR { manufacturer: string; rating: number; }
const carLabel = (c: Car) => (c.manufacturer?.name ?? '') + '/' + c.model;

@Component({
  standalone: true,
  imports: [FormsModule],
  template: `
  <h2>Manufacturers</h2>
  <button id="gwt-debug-create-manufacturer" (click)="create()">Create</button>
  @if (editing) {
    <div id="gwt-debug-manufacturer-editor" class="popup">
      <input id="gwt-debug-manufacturer-input" [(ngModel)]="editing.name" />
      <button id="gwt-debug-manufacturer-save" (click)="save()">Save</button>
      <button id="gwt-debug-manufacturer-close" (click)="editing = null">Close</button>
    </div>
  } @else {
  <table id="gwt-debug-manufacturers">
    <thead><tr><th>ID</th><th>Name</th><th>Edit</th><th>Delete</th></tr></thead>
    <tbody>
      @for (m of items; track m.id) {
        <tr><td>{{ m.id }}</td><td>{{ m.name }}</td>
          <td><button (click)="edit(m)">Edit</button></td>
          <td><button (click)="del(m)">Delete</button></td></tr>
      }
    </tbody>
  </table>
  }`,
})
export class ManufacturersComponent implements OnInit {
  private http = inject(HttpClient); private msgs = inject(MessagesService);
  items: Manufacturer[] = []; editing: Manufacturer | null = null;
  ngOnInit() { this.load(); }
  load() { this.http.get<Manufacturer[]>('/api/manufacturers').subscribe((r) => (this.items = r)); }
  create() { this.editing = { name: '' }; }
  edit(m: Manufacturer) { this.editing = { ...m }; }
  save() {
    this.http.post<Manufacturer>('/api/manufacturers', this.editing).subscribe({
      next: (saved) => {
        const i = this.items.findIndex((x) => x.id === saved.id);
        this.items = i >= 0 ? this.items.map((x, j) => (j === i ? saved : x)) : [...this.items, saved];
        this.editing = null; this.msgs.success('Manufacturer saved');
      },
      error: () => this.msgs.error('Failed to save manufacturer'),
    });
  }
  del(m: Manufacturer) {
    if (!window.confirm('Are you sure you want to delete ' + m.name + '?')) return;
    this.http.delete('/api/manufacturers/' + m.id).subscribe({
      next: () => { this.items = this.items.filter((x) => x !== m); this.msgs.success('Manufacturer deleted'); },
      error: () => this.msgs.error('Failed to delete manufacturer'),
    });
  }
}

@Component({
  standalone: true,
  imports: [FormsModule],
  template: `
  <h2>Ratings</h2>
  <button id="gwt-debug-ratingCreate" (click)="create()">Create</button>
  @if (editing) {
    <div class="popup">
      <select [(ngModel)]="editing.car">
        @for (c of cars; track c.id) { <option [ngValue]="c">{{ label(c) }}</option> }
      </select>
      <input id="gwt-debug-ratingInput" type="number" maxlength="3" [(ngModel)]="editing.rating" />
      <button id="gwt-debug-ratingSave" (click)="save()">Save</button>
      <button (click)="editing = null">Close</button>
    </div>
  }
  <table id="gwt-debug-ratings">
    <thead><tr><th>ID</th><th>Car</th><th>Rating</th><th>Delete</th></tr></thead>
    <tbody>
      @for (r of items; track r.id) {
        <tr><td>{{ r.id }}</td><td>{{ label(r.car) }}</td><td>{{ r.rating }}</td>
          <td><button (click)="del(r)">Delete</button></td></tr>
      }
    </tbody>
  </table>`,
})
export class RatingsComponent implements OnInit {
  private http = inject(HttpClient); private msgs = inject(MessagesService);
  items: Rating[] = []; cars: Car[] = []; editing: Rating | null = null;
  label = carLabel;
  ngOnInit() {
    this.load();
    this.http.get<Car[]>('/api/cars').subscribe((r) => (this.cars = r));
  }
  load() { this.http.get<Rating[]>('/api/ratings').subscribe((r) => (this.items = r)); }
  create() { this.editing = { rating: undefined as unknown as number, car: this.cars[0] }; }
  save() {
    this.http.post<Rating>('/api/ratings', this.editing).subscribe({
      next: (saved) => { this.items = [...this.items, saved]; this.editing = null; this.msgs.success('Rating saved'); },
      error: () => this.msgs.error('Failed to save rating'),
    });
  }
  del(r: Rating) {
    if (!window.confirm('Are you sure you want to delete this rating?')) return;
    this.http.delete('/api/ratings/' + r.id).subscribe({
      next: () => { this.items = this.items.filter((x) => x !== r); this.msgs.success('Rating deleted'); },
      error: () => this.msgs.error('Failed to delete rating'),
    });
  }
}

@Component({
  standalone: true,
  template: `
  <h2>Reports</h2>
  <table id="gwt-debug-reports">
    <thead><tr><th>Manufacturer</th><th>Rating</th></tr></thead>
    <tbody>
      @for (r of items; track r.manufacturer) { <tr><td>{{ r.manufacturer }}</td><td>{{ r.rating }}</td></tr> }
    </tbody>
  </table>`,
})
export class ReportsComponent implements OnInit {
  private http = inject(HttpClient);
  items: MR[] = [];
  ngOnInit() { this.http.get<MR[]>('/api/manufacturers/ratings').subscribe((r) => (this.items = r)); }
}
